-- DATOS FICTICIOS SOLO PARA BASE DE PRACTICAS VACIA. NO USAR EN PRODUCCION.
-- Ejecutar despues de schema_sqlserver.sql, en BibliotecaEscolar_U3.
-- Este script RECHAZA su ejecucion si alguna tabla del proyecto ya tiene registros.
IF DB_ID(N'BibliotecaEscolar_U3') IS NULL THROW 50003, N'Base de datos inexistente.', 1;
GO
USE [BibliotecaEscolar_U3];
GO
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF EXISTS (SELECT 1 FROM biblioteca.persona) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.estudiante) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.docente) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.persona_telefono) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.libro) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.autor) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.libro_autor) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.coleccion) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.libro_coleccion) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.ejemplar) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.prestamo) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
IF EXISTS (SELECT 1 FROM biblioteca.incidencia) THROW 50004, N'La base ya contiene datos; se cancela la carga demo.', 1;
SET IDENTITY_INSERT biblioteca.persona ON;
SET IDENTITY_INSERT biblioteca.persona OFF;
SET IDENTITY_INSERT biblioteca.autor ON;
SET IDENTITY_INSERT biblioteca.autor OFF;
SET IDENTITY_INSERT biblioteca.coleccion ON;
SET IDENTITY_INSERT biblioteca.coleccion OFF;
SET IDENTITY_INSERT biblioteca.ejemplar ON;
SET IDENTITY_INSERT biblioteca.ejemplar OFF;
SET IDENTITY_INSERT biblioteca.prestamo ON;
SET IDENTITY_INSERT biblioteca.prestamo OFF;
SET IDENTITY_INSERT biblioteca.incidencia ON;
SET IDENTITY_INSERT biblioteca.incidencia OFF;
COMMIT TRANSACTION;
PRINT N'Datos ficticios insertados. Ejecute consultas_sqlserver.sql.';
GO